WITH ids AS (SELECT id FROM studies WHERE id::string IN (SELECT DISTINCT study_id::string FROM study_confs) AND slug LIKE '%bangladesh%'),
x AS (SELECT e.study_id, c.key AS camp, s.key AS strat, coalesce(s.value->>'date_start', e.period_start::date::string) AS d, max((s.value->>'spend')::float8) AS spend, max((s.value->>'impressions')::float8) AS imp FROM recruitment_data_events e, jsonb_each(e.data) AS c, jsonb_each(c.value) AS s WHERE e.study_id IN (SELECT id FROM ids) AND jsonb_typeof(c.value)='object' AND jsonb_typeof(s.value)='object' AND s.value->>'spend' IS NOT NULL GROUP BY 1,2,3,4)
SELECT st.slug, x.camp, count(DISTINCT x.strat) nstrat, round(sum(x.spend)::numeric,2) spend, sum(x.imp) imp, round((1000*sum(x.spend)/nullif(sum(x.imp),0))::numeric,2) cpm, min(x.d) d0, max(x.d) d1, count(DISTINCT x.d) days FROM x JOIN studies st ON st.id=x.study_id GROUP BY 1,2 ORDER BY 1,2;
